const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextInt() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        let sign = 1;
        if (input.charCodeAt(pos) === 45) { // '-'
            sign = -1;
            pos++;
        }
        let res = 0;
        while (pos < input.length && input.charCodeAt(pos) >= 48 && input.charCodeAt(pos) <= 57) {
            res = res * 10 + (input.charCodeAt(pos) - 48);
            pos++;
        }
        return res * sign;
    }

    const S = nextInt();
    if (S === null) return;
    const T = nextInt();
    const P = nextInt();

    const A = new Int32Array(S + 1);
    for (let i = 1; i <= S; i++) {
        A[i] = nextInt();
    }

    const adj = Array.from({ length: S + 1 }, () => []);

    for (let k = 0; k < T; k++) {
        const u = nextInt();
        const v = nextInt();
        if (A[u] > A[v]) {
            adj[u].push(v);
        } else if (A[v] > A[u]) {
            adj[v].push(u);
        }
    }

    const memo = new Int32Array(S + 1).fill(-1);

    function dfs(u) {
        if (memo[u] !== -1) return memo[u];
        let maxLen = 0;
        const neighbors = adj[u];
        for (let i = 0; i < neighbors.length; i++) {
            const v = neighbors[i];
            const len = 1 + dfs(v);
            if (len > maxLen) {
                maxLen = len;
            }
        }
        memo[u] = maxLen;
        return maxLen;
    }

    const ans = dfs(P);
    console.log(ans);
}

main();
